#pragma once

#include <vector>
#include <fstream>
#include <iomanip>
#include <iostream>

using namespace std;

inline constexpr int mnist_class_count = 10;
inline constexpr int mnist_feature_dim = 784;

vector<double> plain_scores(
    const vector<double>& x,
    const vector<vector<double>>& weights,
    const vector<double>& bias
) {
    vector<double> scores(mnist_class_count, 0.0);

    for (size_t k = 0; k < weights.size(); ++k) {
        double score = bias[k];
        for (size_t i = 0; i < x.size(); ++i) {
            score += weights[k][i] * x[i];
        }
        scores[k] = score;
    }

    return scores;
}

vector<double> load_input_vector(const string& path) {
    ifstream in(path);
    if (!in) {
        throw runtime_error("failed to open input vector file: " + path);
    }

    vector<double> x;
    double value = 0.0;
    while (in >> value) {
        x.push_back(value);
    }

    return x;
}

